# Media Encoder: a project generated by After Effects is queued in Media Encoder as an H.264 job; the encoded file is checked on the host
# (duration, codec, size) and the encoder engine is sampled by the caller.
. 'C:\kfhw\lib.ps1'
$R = Init-Run 'mediaencoder'
$base = 'C:\Program Files\Adobe\Adobe After Effects 2027\Support Files'
try {
  $js = $AE_MAKE
  if ($js.Length -lt 100) { throw 'ae_make.jsx missing' }
  $js = $js.Replace('@MODE@', 'ame').Replace('@OUT@', ($D -replace '\\', '/')).Replace('@VIDEO@', '')
  Set-Content "$D\ae_make_run.jsx" $js
  $p = Start-Process "$base\AfterFX.exe" -ArgumentList @('-r', "$D\ae_make_run.jsx") -PassThru
  $mp4 = "$D\ame_out.mp4"
  $t0 = Get-Date
  $last = -1; $stable = 0
  while (((Get-Date) - $t0).TotalSeconds -lt 420) {
    [void](Dismiss-Dialogs @('AfterFX', 'Adobe Media Encoder'))
    if (Test-Path $mp4) { $len = (Get-Item $mp4).Length; if ($len -gt 0 -and $len -eq $last) { $stable++ } else { $stable = 0 }; $last = $len }
    if ($stable -ge 5 -and (Test-Path "$D\ame_make.ok")) { break }
    if (Test-Path "$D\ae_make.txt") { Set-Content "$D\ame_make.ok" 'x' }
    Start-Sleep 3
  }
  $R.make_log = (Get-Content "$D\ae_make.txt" -Raw -ErrorAction SilentlyContinue)
  if (-not (Test-Path $mp4)) { throw ('no encoded file; AE script said: ' + $R.make_log) }
  $R.outputs = @(File-Info $mp4)
  $q1 = Quit-App 'Adobe Media Encoder'
  $q2 = Quit-App 'AfterFX'
  $R.quit = if ($q1 -eq 'clean' -and $q2 -eq 'clean') { 'clean' } else { "$q1/$q2" }
} catch { $R.error = $_.Exception.Message; $R.quit = (Quit-App 'Adobe Media Encoder') + '/' + (Quit-App 'AfterFX') }
Finish $R
